package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.builder.EqualsBuilder;
import org.apache.commons.lang3.builder.ToStringBuilder;
import org.apache.commons.lang3.builder.ToStringStyle;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.ArrayUtils.add(T[] array, T element)
 */
public class ArrayUtils_add_TriageGen3Test {

    @Test
    public void testAdd_WithExistingArray() {
        String[] input = {"A", "B"};
        String element = "C";
        String[] expected = {"A", "B", "C"};
        String[] result = ArrayUtils.add(input, element);

        assertArrayEquals(expected, result);
        assertEquals(3, result.length);
        // Verify it's a new array instance (immutability check)
        assertNotSame(input, result);
    }

    @Test
    public void testAdd_WithNullArrayAndNonNullElement() {
        // Covers the branch: else if (element != null) { type = element.getClass(); }
        Integer[] input = null;
        Integer element = 10;
        Integer[] expected = {10};
        Integer[] result = ArrayUtils.add(input, element);

        assertArrayEquals(expected, result);
        assertEquals(1, result.length);
    }

    @Test
    public void testAdd_WithNullArrayAndNullElement() {
        // Covers the branch: else { type = Object.class; }
        Object[] input = null;
        Object element = null;
        Object[] result = ArrayUtils.add(input, element);

        assertNotNull(result);
        assertEquals(1, result.length);
        assertNull(result[0]);
    }

    @Test
    public void testAdd_WithEmptyArray() {
        String[] input = {};
        String element = "New";
        String[] expected = {"New"};
        String[] result = ArrayUtils.add(input, element);

        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_WithIntegerArray() {
        Integer[] input = {1, 2};
        Integer element = 3;
        Integer[] expected = {1, 2, 3};
        Integer[] result = ArrayUtils.add(input, element);

        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_PreservesType() {
        // Ensures that the returned array is of the correct component type
        Double[] input = {1.1, 2.2};
        Double element = 3.3;
        Double[] result = ArrayUtils.add(input, element);

        assertTrue(java.lang.reflect.Array.newInstance(Double.class, 3).getClass().isArray());
        assertEquals(Double.class, result.getClass().getComponentType());
    }

    @Test
    public void testAdd_WithMixedObjects() {
        // Testing the Object.class fallback logic
        Object[] input = {"String", 123};
        Object element = true;
        Object[] expected = {"String", 123, true};
        Object[] result = ArrayUtils.add(input, element);

        assertArrayEquals(expected, result);
    }
}
